CREATE VIEW "conflict_search_data_view" AS (select "conflicts"."id", 'conflicts' as "source_table", to_jsonb("conflicts".*) as "entity_main", COALESCE(jsonb_build_object('id', "regions"."id", 'name', "regions"."name"), '{}'::jsonb) as "region", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('participant', to_jsonb("conflict_participants".*), 'faction', CASE WHEN "conflict_participants"."faction_id" IS NOT NULL THEN jsonb_build_object('id', "factions"."id", 'name', "factions"."name") END, 'npc', CASE WHEN "conflict_participants"."npc_id" IS NOT NULL THEN jsonb_build_object('id', "npcs"."id", 'name', "npcs"."name") END)) FILTER (WHERE "conflict_participants"."id" IS NOT NULL), '[]'::jsonb) as "participants", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "affected_by_consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("foreshadowing".*)) FILTER (WHERE "foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("item_connections".*)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "item_connections", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "lore_links"."id", 'lore_id', "lore_links"."lore_id")) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "lore_links" from "conflicts" left join "regions" on "conflicts"."region_id" = "regions"."id" left join "conflict_participants" on "conflict_participants"."conflict_id" = "conflicts"."id" left join "factions" on "conflict_participants"."faction_id" = "factions"."id" left join "npcs" on "conflict_participants"."npc_id" = "npcs"."id" left join "consequences" on "consequences"."affected_conflict_id" = "conflicts"."id" left join "foreshadowing" on "foreshadowing"."target_conflict_id" = "conflicts"."id" left join "item_connections" on "item_connections"."connected_conflict_id" = "conflicts"."id" left join "lore_links" on "lore_links"."conflict_id" = "conflicts"."id" group by "conflicts"."id", "regions"."id");--> statement-breakpoint
CREATE VIEW "consequence_search_data_view" AS (select "consequences"."id", 'consequences' as "source_table", to_jsonb("consequences".*) as "entity_main", COALESCE(jsonb_build_object('id', tq.id, 'name', tq.name), '{}'::jsonb) as "trigger_quest", COALESCE(jsonb_build_object('id', af.id, 'name', af.name), '{}'::jsonb) as "affected_faction", COALESCE(jsonb_build_object('id', ar.id, 'name', ar.name), '{}'::jsonb) as "affected_region", COALESCE(jsonb_build_object('id', aa.id, 'name', aa.name), '{}'::jsonb) as "affected_area", COALESCE(jsonb_build_object('id', as_.id, 'name', as_.name), '{}'::jsonb) as "affected_site", COALESCE(jsonb_build_object('id', an.id, 'name', an.name), '{}'::jsonb) as "affected_npc", COALESCE(jsonb_build_object('id', ac.id, 'name', ac.name), '{}'::jsonb) as "affected_conflict", COALESCE(jsonb_build_object('id', aq.id, 'name', aq.name), '{}'::jsonb) as "affected_quest" from "consequences" left join "quests" AS tq on "consequences"."trigger_quest_id" = tq.id left join "factions" AS af on "consequences"."affected_faction_id" = af.id left join "regions" AS ar on "consequences"."affected_region_id" = ar.id left join "areas" AS aa on "consequences"."affected_area_id" = aa.id left join "sites" AS as_ on "consequences"."affected_site_id" = as_.id left join "npcs" AS an on "consequences"."affected_npc_id" = an.id left join "conflicts" AS ac on "consequences"."affected_conflict_id" = ac.id left join "quests" AS aq on "consequences"."affected_quest_id" = aq.id group by "consequences"."id", tq.id, af.id, ar.id, aa.id, as_.id, an.id, ac.id, aq.id);--> statement-breakpoint
CREATE VIEW "faction_search_data_view" AS (select "factions"."id", 'factions' as "source_table", to_jsonb("factions") as "entity_main", COALESCE(jsonb_build_object('id', "sites"."id", 'name', "sites"."name"), '{}'::jsonb) as "primaryHqSite", COALESCE(jsonb_agg(DISTINCT to_jsonb("faction_agendas".*)) FILTER (WHERE "faction_agendas"."id" IS NOT NULL), '[]'::jsonb) as "agendas", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('membership', to_jsonb("npc_faction_memberships".*), 'npc', jsonb_build_object('id', "npcs"."id", 'name', "npcs"."name"))) FILTER (WHERE "npc_faction_memberships"."id" IS NOT NULL), '[]'::jsonb) as "members", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "quest_hooks"."id", 'source', "quest_hooks"."source", 'hook_content', "quest_hooks"."hook_content")) FILTER (WHERE "quest_hooks"."id" IS NOT NULL), '[]'::jsonb) as "questHooks", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('participation', to_jsonb(qp.*), 'quest', jsonb_build_object('id', q.id, 'name', q.name))) FILTER (WHERE qp.id IS NOT NULL), '[]'::jsonb) as "questParticipation", COALESCE(jsonb_agg(DISTINCT jsonb_build_object(
      'influence', to_jsonb("faction_influence".*),
      'region', CASE WHEN "faction_influence"."region_id" IS NOT NULL THEN jsonb_build_object('id', r.id, 'name', r.name) END,
      'area', CASE WHEN "faction_influence"."area_id" IS NOT NULL THEN jsonb_build_object('id', a.id, 'name', a.name) END,
      'site', CASE WHEN "faction_influence"."site_id" IS NOT NULL THEN jsonb_build_object('id', s.id, 'name', s.name) END
    )) FILTER (WHERE "faction_influence"."id" IS NOT NULL), '[]'::jsonb) as "influence", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('participant', to_jsonb("conflict_participants".*), 'conflict', jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name"))) FILTER (WHERE "conflict_participants"."id" IS NOT NULL), '[]'::jsonb) as "conflicts", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("foreshadowing".*)) FILTER (WHERE "foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incomingForeshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("item_connections".*)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "itemConnections", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "lore_links"."id", 'lore_id', "lore_links"."lore_id")) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "loreLinks", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relation', to_jsonb(fd_in.*), 'sourceFaction', jsonb_build_object('id', sf.id, 'name', sf.name))) FILTER (WHERE fd_in.id IS NOT NULL), '[]'::jsonb) as "incomingRelations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relation', to_jsonb(fd_out.*), 'targetFaction', jsonb_build_object('id', tf.id, 'name', tf.name))) FILTER (WHERE fd_out.id IS NOT NULL), '[]'::jsonb) as "outgoingRelations" from "factions" left join "sites" on "factions"."hq_site_id" = "sites"."id" left join "faction_agendas" on "faction_agendas"."faction_id" = "factions"."id" left join "npc_faction_memberships" on "npc_faction_memberships"."faction_id" = "factions"."id" left join "npcs" on "npc_faction_memberships"."npc_id" = "npcs"."id" left join "quest_hooks" on "quest_hooks"."faction_id" = "factions"."id" left join "quest_participants" AS qp on qp.faction_id = "factions"."id" left join "quests" AS q on qp.quest_id = q.id left join "faction_influence" on "faction_influence"."faction_id" = "factions"."id" left join "regions" AS r on "faction_influence"."region_id" = r.id left join "areas" AS a on "faction_influence"."area_id" = a.id left join "sites" AS s on "faction_influence"."site_id" = s.id left join "conflict_participants" on "conflict_participants"."faction_id" = "factions"."id" left join "conflicts" on "conflict_participants"."conflict_id" = "conflicts"."id" left join "consequences" on "consequences"."affected_faction_id" = "factions"."id" left join "foreshadowing" on "foreshadowing"."target_faction_id" = "factions"."id" left join "item_connections" on "item_connections"."connected_faction_id" = "factions"."id" left join "lore_links" on "lore_links"."faction_id" = "factions"."id" left join "faction_diplomacy" AS fd_in on fd_in.target_faction_id = "factions"."id" left join "factions" AS sf on fd_in.source_faction_id = sf.id left join "faction_diplomacy" AS fd_out on fd_out.source_faction_id = "factions"."id" left join "factions" AS tf on fd_out.target_faction_id = tf.id group by "factions"."id", "sites"."id");--> statement-breakpoint
CREATE VIEW "foreshadowing_search_data_view" AS (select "foreshadowing"."id", 'foreshadowing' as "source_table", to_jsonb("foreshadowing".*) as "entity_main", CASE WHEN "foreshadowing"."source_quest_id" IS NOT NULL THEN jsonb_build_object('id', "source_quest"."id", 'name', "source_quest"."name") END as "source_quest", CASE WHEN "foreshadowing"."source_quest_stage_id" IS NOT NULL THEN jsonb_build_object(
				'stage', jsonb_build_object('id', "quest_stages"."id", 'name', "quest_stages"."name"),
				'quest', jsonb_build_object('id', "source_stage_quest"."id", 'name', "source_stage_quest"."name")
			) END as "source_quest_stage", CASE WHEN "foreshadowing"."source_site_id" IS NOT NULL THEN jsonb_build_object('id', "source_site"."id", 'name', "source_site"."name") END as "source_site", CASE WHEN "foreshadowing"."source_npc_id" IS NOT NULL THEN jsonb_build_object('id', "source_npc"."id", 'name', "source_npc"."name") END as "source_npc", CASE WHEN "foreshadowing"."source_lore_id" IS NOT NULL THEN jsonb_build_object('id', "source_lore"."id", 'name', "source_lore"."name") END as "source_lore", CASE WHEN "foreshadowing"."target_quest_id" IS NOT NULL THEN jsonb_build_object('id', "target_quest"."id", 'name', "target_quest"."name") END as "target_quest", CASE WHEN "foreshadowing"."target_npc_id" IS NOT NULL THEN jsonb_build_object('id', "target_npc"."id", 'name', "target_npc"."name") END as "target_npc", CASE WHEN "foreshadowing"."target_conflict_id" IS NOT NULL THEN jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name") END as "target_conflict", CASE WHEN "foreshadowing"."target_item_id" IS NOT NULL THEN jsonb_build_object('id', "items"."id", 'name', "items"."name") END as "target_item", CASE WHEN "foreshadowing"."target_lore_id" IS NOT NULL THEN jsonb_build_object('id', "target_lore"."id", 'name', "target_lore"."name") END as "target_lore", CASE WHEN "foreshadowing"."target_faction_id" IS NOT NULL THEN jsonb_build_object('id', "factions"."id", 'name', "factions"."name") END as "target_faction", CASE WHEN "foreshadowing"."target_site_id" IS NOT NULL THEN jsonb_build_object('id', "target_site"."id", 'name', "target_site"."name") END as "target_site" from "foreshadowing" left join "quests" "source_quest" on "foreshadowing"."source_quest_id" = "source_quest"."id" left join "quest_stages" on "foreshadowing"."source_quest_stage_id" = "quest_stages"."id" left join "quests" "source_stage_quest" on "quest_stages"."quest_id" = "source_stage_quest"."id" left join "sites" "source_site" on "foreshadowing"."source_site_id" = "source_site"."id" left join "npcs" "source_npc" on "foreshadowing"."source_npc_id" = "source_npc"."id" left join "lore" "source_lore" on "foreshadowing"."source_lore_id" = "source_lore"."id" left join "quests" "target_quest" on "foreshadowing"."target_quest_id" = "target_quest"."id" left join "npcs" "target_npc" on "foreshadowing"."target_npc_id" = "target_npc"."id" left join "conflicts" on "foreshadowing"."target_conflict_id" = "conflicts"."id" left join "items" on "foreshadowing"."target_item_id" = "items"."id" left join "lore" "target_lore" on "foreshadowing"."target_lore_id" = "target_lore"."id" left join "factions" on "foreshadowing"."target_faction_id" = "factions"."id" left join "sites" "target_site" on "foreshadowing"."target_site_id" = "target_site"."id");--> statement-breakpoint
CREATE VIEW "item_search_data_view" AS (select "items"."id", 'items' as "source_table", to_jsonb("items".*) as "entity_main", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("item_connections".*), 'item', CASE WHEN "item_connections"."connected_item_id" IS NOT NULL THEN jsonb_build_object('id', "connected_item"."id", 'name', "connected_item"."name") END, 'npc', CASE WHEN "item_connections"."connected_npc_id" IS NOT NULL THEN jsonb_build_object('id', "npcs"."id", 'name', "npcs"."name") END, 'faction', CASE WHEN "item_connections"."connected_faction_id" IS NOT NULL THEN jsonb_build_object('id', "factions"."id", 'name', "factions"."name") END, 'site', CASE WHEN "item_connections"."connected_site_id" IS NOT NULL THEN jsonb_build_object('id', "sites"."id", 'name', "sites"."name") END, 'quest', CASE WHEN "item_connections"."connected_quest_id" IS NOT NULL THEN jsonb_build_object('id', "quests"."id", 'name', "quests"."name") END, 'conflict', CASE WHEN "item_connections"."connected_conflict_id" IS NOT NULL THEN jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name") END, 'lore', CASE WHEN "item_connections"."connected_lore_id" IS NOT NULL THEN jsonb_build_object('id', "lore"."id", 'name', "lore"."name") END, 'questStage', CASE WHEN "item_connections"."connected_quest_stage_id" IS NOT NULL THEN jsonb_build_object('id', "quest_stages"."id", 'name', "quest_stages"."name") END)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("incoming_connections".*), 'sourceItem', jsonb_build_object('id', "incoming_source_item"."id", 'name', "incoming_source_item"."name"))) FILTER (WHERE "incoming_connections"."id" IS NOT NULL), '[]'::jsonb) as "incoming_relations", COALESCE(jsonb_agg(DISTINCT to_jsonb("foreshadowing".*)) FILTER (WHERE "foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing" from "items" left join "item_connections" on "item_connections"."source_item_id" = "items"."id" left join "items" "connected_item" on "item_connections"."connected_item_id" = "connected_item"."id" left join "npcs" on "item_connections"."connected_npc_id" = "npcs"."id" left join "factions" on "item_connections"."connected_faction_id" = "factions"."id" left join "sites" on "item_connections"."connected_site_id" = "sites"."id" left join "quests" on "item_connections"."connected_quest_id" = "quests"."id" left join "conflicts" on "item_connections"."connected_conflict_id" = "conflicts"."id" left join "lore" on "item_connections"."connected_lore_id" = "lore"."id" left join "quest_stages" on "item_connections"."connected_quest_stage_id" = "quest_stages"."id" left join "item_connections" "incoming_connections" on "incoming_connections"."connected_item_id" = "items"."id" left join "items" "incoming_source_item" on "incoming_connections"."source_item_id" = "incoming_source_item"."id" left join "foreshadowing" on "foreshadowing"."target_item_id" = "items"."id" group by "items"."id");--> statement-breakpoint
CREATE VIEW "lore_search_data_view" AS (select "lore"."id", 'lore' as "source_table", to_jsonb("lore".*) as "entity_main", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('link', to_jsonb("lore_links".*), 'region', CASE WHEN "lore_links"."region_id" IS NOT NULL THEN jsonb_build_object('id', "regions"."id", 'name', "regions"."name") END, 'faction', CASE WHEN "lore_links"."faction_id" IS NOT NULL THEN jsonb_build_object('id', "factions"."id", 'name', "factions"."name") END, 'npc', CASE WHEN "lore_links"."npc_id" IS NOT NULL THEN jsonb_build_object('id', "npcs"."id", 'name', "npcs"."name") END, 'conflict', CASE WHEN "lore_links"."conflict_id" IS NOT NULL THEN jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name") END, 'quest', CASE WHEN "lore_links"."quest_id" IS NOT NULL THEN jsonb_build_object('id', "quests"."id", 'name', "quests"."name") END, 'item', CASE WHEN "lore_links"."item_id" IS NOT NULL THEN jsonb_build_object('id', "items"."id", 'name', "items"."name") END, 'relatedLore', CASE WHEN "lore_links"."related_lore_id" IS NOT NULL THEN jsonb_build_object('id', "related_lore"."id", 'name', "related_lore"."name") END, 'foreshadowing', CASE WHEN "lore_links"."foreshadowing_id" IS NOT NULL THEN jsonb_build_object('id', "linked_foreshadowing"."id", 'name', "linked_foreshadowing"."name") END)) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "links", COALESCE(jsonb_agg(DISTINCT to_jsonb("foreshadowing".*)) FILTER (WHERE "foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("outgoing_foreshadowing".*)) FILTER (WHERE "outgoing_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_foreshadowing" from "lore" left join "lore_links" on "lore_links"."lore_id" = "lore"."id" left join "regions" on "lore_links"."region_id" = "regions"."id" left join "factions" on "lore_links"."faction_id" = "factions"."id" left join "npcs" on "lore_links"."npc_id" = "npcs"."id" left join "conflicts" on "lore_links"."conflict_id" = "conflicts"."id" left join "quests" on "lore_links"."quest_id" = "quests"."id" left join "items" on "lore_links"."item_id" = "items"."id" left join "lore" "related_lore" on "lore_links"."related_lore_id" = "related_lore"."id" left join "foreshadowing" "linked_foreshadowing" on "lore_links"."foreshadowing_id" = "linked_foreshadowing"."id" left join "foreshadowing" "outgoing_foreshadowing" on "outgoing_foreshadowing"."source_lore_id" = "lore"."id" left join "foreshadowing" on "foreshadowing"."target_lore_id" = "lore"."id" group by "lore"."id");--> statement-breakpoint
CREATE VIEW "npc_search_data_view" AS (select "npcs"."id", 'npcs' as "source_table", to_jsonb("npcs".*) as "entity_main", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('membership', to_jsonb("npc_faction_memberships".*), 'faction', jsonb_build_object('id', "factions"."id", 'name', "factions"."name"))) FILTER (WHERE "npc_faction_memberships"."id" IS NOT NULL), '[]'::jsonb) as "faction_memberships", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('participant', to_jsonb("conflict_participants".*), 'conflict', jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name"))) FILTER (WHERE "conflict_participants"."id" IS NOT NULL), '[]'::jsonb) as "conflict_participation", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "affected_by_consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("outgoing_foreshadowing".*)) FILTER (WHERE "outgoing_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("incoming_foreshadowing".*)) FILTER (WHERE "incoming_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("item_connections".*)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "item_connections", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "quest_hooks"."id", 'source', "quest_hooks"."source", 'hook_content', "quest_hooks"."hook_content", 'quest', jsonb_build_object('id', "hook_quest"."id", 'name', "hook_quest"."name"))) FILTER (WHERE "quest_hooks"."id" IS NOT NULL), '[]'::jsonb) as "quest_hooks", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('stage', jsonb_build_object('id', "delivery_stage"."id", 'name', "delivery_stage"."name"), 'quest', jsonb_build_object('id', "delivery_stage_quest"."id", 'name', "delivery_stage_quest"."name"))) FILTER (WHERE "delivery_stage"."id" IS NOT NULL), '[]'::jsonb) as "quest_stage_deliveries", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('involvement', to_jsonb("npc_quest_stage_involvement".*), 'stage', jsonb_build_object('id', "involvement_stage"."id", 'name', "involvement_stage"."name"), 'quest', jsonb_build_object('id', "involvement_quest"."id", 'name', "involvement_quest"."name"))) FILTER (WHERE "npc_quest_stage_involvement"."id" IS NOT NULL), '[]'::jsonb) as "stage_involvement", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "lore_links"."id", 'lore_id', "lore_links"."lore_id")) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "lore_links", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("outgoing_relations".*), 'relatedNpc', jsonb_build_object('id', "related_npc"."id", 'name', "related_npc"."name"))) FILTER (WHERE "outgoing_relations"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("incoming_relations".*), 'sourceNpc', jsonb_build_object('id', "source_npc"."id", 'name', "source_npc"."name"))) FILTER (WHERE "incoming_relations"."id" IS NOT NULL), '[]'::jsonb) as "incoming_relations", COALESCE(jsonb_agg(DISTINCT to_jsonb("sites".*)) FILTER (WHERE "sites"."id" IS NOT NULL), '[]'::jsonb) as "site_associations" from "npcs" left join "npc_faction_memberships" on "npc_faction_memberships"."npc_id" = "npcs"."id" left join "factions" on "npc_faction_memberships"."faction_id" = "factions"."id" left join "sites" on "npcs"."site_id" = "sites"."id" left join "conflict_participants" on "conflict_participants"."npc_id" = "npcs"."id" left join "conflicts" on "conflict_participants"."conflict_id" = "conflicts"."id" left join "consequences" on "consequences"."affected_npc_id" = "npcs"."id" left join "foreshadowing" "outgoing_foreshadowing" on "outgoing_foreshadowing"."source_npc_id" = "npcs"."id" left join "foreshadowing" "incoming_foreshadowing" on "incoming_foreshadowing"."target_npc_id" = "npcs"."id" left join "item_connections" on "item_connections"."connected_npc_id" = "npcs"."id" left join "quest_hooks" on "quest_hooks"."delivery_npc_id" = "npcs"."id" left join "quests" "hook_quest" on "quest_hooks"."quest_id" = "hook_quest"."id" left join "quest_stages" "delivery_stage" on "delivery_stage"."delivery_npc_id" = "npcs"."id" left join "quests" "delivery_stage_quest" on "delivery_stage"."quest_id" = "delivery_stage_quest"."id" left join "npc_quest_stage_involvement" on "npc_quest_stage_involvement"."npc_id" = "npcs"."id" left join "quest_stages" "involvement_stage" on "npc_quest_stage_involvement"."quest_stage_id" = "involvement_stage"."id" left join "quests" "involvement_quest" on "involvement_stage"."quest_id" = "involvement_quest"."id" left join "lore_links" on "lore_links"."npc_id" = "npcs"."id" left join "npc_relations" "outgoing_relations" on "outgoing_relations"."source_npc_id" = "npcs"."id" left join "npcs" "related_npc" on "outgoing_relations"."target_npc_id" = "related_npc"."id" left join "npc_relations" "incoming_relations" on "incoming_relations"."target_npc_id" = "npcs"."id" left join "npcs" "source_npc" on "incoming_relations"."source_npc_id" = "source_npc"."id" group by "npcs"."id");--> statement-breakpoint
CREATE VIEW "quest_search_data_view" AS (select "quests"."id", 'quests' as "source_table", to_jsonb("quests".*) as "entity_main", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("outgoing_relations".*), 'targetQuest', jsonb_build_object('id', "target_quest"."id", 'name', "target_quest"."name"))) FILTER (WHERE "outgoing_relations"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('relationship', to_jsonb("incoming_relations".*), 'sourceQuest', jsonb_build_object('id', "source_quest"."id", 'name', "source_quest"."name"))) FILTER (WHERE "incoming_relations"."id" IS NOT NULL), '[]'::jsonb) as "incoming_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "quest_stages"."id", 'name', "quest_stages"."name", 'stage_order', "quest_stages"."stage_order", 'stage_type', "quest_stages"."stage_type", 'deliveryNpc', CASE WHEN "quest_stages"."delivery_npc_id" IS NOT NULL THEN jsonb_build_object('id', "stage_delivery_npc"."id", 'name', "stage_delivery_npc"."name") END)) FILTER (WHERE "quest_stages"."id" IS NOT NULL), '[]'::jsonb) as "stages", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('hook', to_jsonb("quest_hooks".*), 'site', CASE WHEN "quest_hooks"."site_id" IS NOT NULL THEN jsonb_build_object('id', "hook_site"."id", 'name', "hook_site"."name") END, 'faction', CASE WHEN "quest_hooks"."faction_id" IS NOT NULL THEN jsonb_build_object('id', "hook_faction"."id", 'name', "hook_faction"."name") END, 'deliveryNpc', CASE WHEN "quest_hooks"."delivery_npc_id" IS NOT NULL THEN jsonb_build_object('id', "hook_npc"."id", 'name', "hook_npc"."name") END)) FILTER (WHERE "quest_hooks"."id" IS NOT NULL), '[]'::jsonb) as "hooks", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('involvement', to_jsonb("quest_participants".*), 'npc', CASE WHEN "quest_participants"."npc_id" IS NOT NULL THEN jsonb_build_object('id', "participant_npc"."id", 'name', "participant_npc"."name") END, 'faction', CASE WHEN "quest_participants"."faction_id" IS NOT NULL THEN jsonb_build_object('id', "participant_faction"."id", 'name', "participant_faction"."name") END)) FILTER (WHERE "quest_participants"."id" IS NOT NULL), '[]'::jsonb) as "participants", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "triggered_consequences"."id", 'name', "triggered_consequences"."name", 'description', "triggered_consequences"."description")) FILTER (WHERE "triggered_consequences"."id" IS NOT NULL), '[]'::jsonb) as "triggered_consequences", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "affecting_consequences"."id", 'name', "affecting_consequences"."name", 'description', "affecting_consequences"."description")) FILTER (WHERE "affecting_consequences"."id" IS NOT NULL), '[]'::jsonb) as "affecting_consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("outgoing_foreshadowing".*)) FILTER (WHERE "outgoing_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("incoming_foreshadowing".*)) FILTER (WHERE "incoming_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("item_connections".*)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "item_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "lore_links"."id", 'lore_id', "lore_links"."lore_id")) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "lore_links" from "quests" left join "quest_relations" "outgoing_relations" on "outgoing_relations"."source_quest_id" = "quests"."id" left join "quests" "target_quest" on "outgoing_relations"."target_quest_id" = "target_quest"."id" left join "quest_relations" "incoming_relations" on "incoming_relations"."target_quest_id" = "quests"."id" left join "quests" "source_quest" on "incoming_relations"."source_quest_id" = "source_quest"."id" left join "quest_stages" on "quest_stages"."quest_id" = "quests"."id" left join "npcs" "stage_delivery_npc" on "quest_stages"."delivery_npc_id" = "stage_delivery_npc"."id" left join "quest_hooks" on "quest_hooks"."quest_id" = "quests"."id" left join "sites" "hook_site" on "quest_hooks"."site_id" = "hook_site"."id" left join "factions" "hook_faction" on "quest_hooks"."faction_id" = "hook_faction"."id" left join "npcs" "hook_npc" on "quest_hooks"."delivery_npc_id" = "hook_npc"."id" left join "quest_participants" on "quest_participants"."quest_id" = "quests"."id" left join "npcs" "participant_npc" on "quest_participants"."npc_id" = "participant_npc"."id" left join "factions" "participant_faction" on "quest_participants"."faction_id" = "participant_faction"."id" left join "consequences" "triggered_consequences" on "triggered_consequences"."trigger_quest_id" = "quests"."id" left join "consequences" "affecting_consequences" on "affecting_consequences"."affected_quest_id" = "quests"."id" left join "foreshadowing" "outgoing_foreshadowing" on "outgoing_foreshadowing"."source_quest_id" = "quests"."id" left join "foreshadowing" "incoming_foreshadowing" on "incoming_foreshadowing"."target_quest_id" = "quests"."id" left join "item_connections" on "item_connections"."connected_quest_id" = "quests"."id" left join "lore_links" on "lore_links"."quest_id" = "quests"."id" group by "quests"."id");--> statement-breakpoint
CREATE VIEW "area_search_data_view" AS (select "areas"."id", 'areas' as "source_table", to_jsonb("areas".*) as "entity_main", jsonb_build_object('id', "regions"."id", 'name', "regions"."name") as "region", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "sites"."id", 'name', "sites"."name", 'description', "sites"."description")) FILTER (WHERE "sites"."id" IS NOT NULL), '[]'::jsonb) as "sites", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("faction_influence".*)) FILTER (WHERE "faction_influence"."id" IS NOT NULL), '[]'::jsonb) as "faction_influence" from "areas" inner join "regions" on "areas"."region_id" = "regions"."id" left join "sites" on "sites"."area_id" = "areas"."id" left join "consequences" on "consequences"."affected_area_id" = "areas"."id" left join "faction_influence" on "faction_influence"."area_id" = "areas"."id" group by "areas"."id", "regions"."id");--> statement-breakpoint
CREATE VIEW "region_search_data_view" AS (select "regions"."id", 'regions' as "source_table", to_jsonb("regions".*) as "entity_main", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('connection', to_jsonb("outgoing_connections".*), 'targetRegion', jsonb_build_object('id', "target_region"."id", 'name', "target_region"."name"))) FILTER (WHERE "outgoing_connections"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('connection', to_jsonb("incoming_connections".*), 'sourceRegion', jsonb_build_object('id', "source_region"."id", 'name', "source_region"."name"))) FILTER (WHERE "incoming_connections"."id" IS NOT NULL), '[]'::jsonb) as "incoming_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "areas"."id", 'name', "areas"."name", 'description', "areas"."description")) FILTER (WHERE "areas"."id" IS NOT NULL), '[]'::jsonb) as "areas", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "conflicts"."id", 'name', "conflicts"."name")) FILTER (WHERE "conflicts"."id" IS NOT NULL), '[]'::jsonb) as "conflicts", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "consequences", COALESCE(jsonb_agg(DISTINCT to_jsonb("faction_influence".*)) FILTER (WHERE "faction_influence"."id" IS NOT NULL), '[]'::jsonb) as "faction_influence", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "lore_links"."id", 'lore_id', "lore_links"."lore_id")) FILTER (WHERE "lore_links"."id" IS NOT NULL), '[]'::jsonb) as "lore_links" from "regions" left join "region_connections" "outgoing_connections" on "outgoing_connections"."source_region_id" = "regions"."id" left join "regions" "target_region" on "outgoing_connections"."target_region_id" = "target_region"."id" left join "region_connections" "incoming_connections" on "incoming_connections"."target_region_id" = "regions"."id" left join "regions" "source_region" on "incoming_connections"."source_region_id" = "source_region"."id" left join "areas" on "areas"."region_id" = "regions"."id" left join "conflicts" on "conflicts"."region_id" = "regions"."id" left join "consequences" on "consequences"."affected_region_id" = "regions"."id" left join "faction_influence" on "faction_influence"."region_id" = "regions"."id" left join "lore_links" on "lore_links"."region_id" = "regions"."id" group by "regions"."id");--> statement-breakpoint
CREATE VIEW "site_search_data_view" AS (select "sites"."id", 'sites' as "source_table", to_jsonb("sites".*) as "entity_main", jsonb_build_object('id', "areas"."id", 'name', "areas"."name", 'region', jsonb_build_object('id', "regions"."id", 'name', "regions"."name")) as "area", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('link', to_jsonb("outgoing_links".*), 'targetSite', jsonb_build_object('id', "target_site"."id", 'name', "target_site"."name"))) FILTER (WHERE "outgoing_links"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_relations", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('link', to_jsonb("incoming_links".*), 'sourceSite', jsonb_build_object('id', "source_site"."id", 'name', "source_site"."name"))) FILTER (WHERE "incoming_links"."id" IS NOT NULL), '[]'::jsonb) as "incoming_relations", COALESCE(jsonb_agg(DISTINCT to_jsonb("site_encounters".*)) FILTER (WHERE "site_encounters"."id" IS NOT NULL), '[]'::jsonb) as "encounters", COALESCE(jsonb_agg(DISTINCT to_jsonb("site_secrets".*)) FILTER (WHERE "site_secrets"."id" IS NOT NULL), '[]'::jsonb) as "secrets", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "quest_stages"."id", 'name', "quest_stages"."name", 'quest', jsonb_build_object('id', "stage_quest"."id", 'name', "stage_quest"."name"))) FILTER (WHERE "quest_stages"."id" IS NOT NULL), '[]'::jsonb) as "quest_stages", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "quest_hooks"."id", 'source', "quest_hooks"."source", 'hook_content', "quest_hooks"."hook_content", 'quest', jsonb_build_object('id', "hook_quest"."id", 'name', "hook_quest"."name"))) FILTER (WHERE "quest_hooks"."id" IS NOT NULL), '[]'::jsonb) as "quest_hooks", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "consequences", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "factions"."id", 'name', "factions"."name")) FILTER (WHERE "factions"."id" IS NOT NULL), '[]'::jsonb) as "faction_hqs", COALESCE(jsonb_agg(DISTINCT to_jsonb("faction_influence".*)) FILTER (WHERE "faction_influence"."id" IS NOT NULL), '[]'::jsonb) as "faction_influence", COALESCE(jsonb_agg(DISTINCT to_jsonb("outgoing_foreshadowing".*)) FILTER (WHERE "outgoing_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("incoming_foreshadowing".*)) FILTER (WHERE "incoming_foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "incoming_foreshadowing", COALESCE(jsonb_agg(DISTINCT to_jsonb("item_connections".*)) FILTER (WHERE "item_connections"."id" IS NOT NULL), '[]'::jsonb) as "item_relations", CASE WHEN "sites"."map_group_id" IS NOT NULL THEN jsonb_build_object('id', "map_groups"."id", 'name', "map_groups"."name") END as "map_group" from "sites" inner join "areas" on "sites"."area_id" = "areas"."id" inner join "regions" on "areas"."region_id" = "regions"."id" left join "site_links" "outgoing_links" on "outgoing_links"."source_site_id" = "sites"."id" left join "sites" "target_site" on "outgoing_links"."target_site_id" = "target_site"."id" left join "site_links" "incoming_links" on "incoming_links"."target_site_id" = "sites"."id" left join "sites" "source_site" on "incoming_links"."source_site_id" = "source_site"."id" left join "site_encounters" on "site_encounters"."site_id" = "sites"."id" left join "site_secrets" on "site_secrets"."site_id" = "sites"."id" left join "quest_stages" on "quest_stages"."site_id" = "sites"."id" left join "quests" "stage_quest" on "quest_stages"."quest_id" = "stage_quest"."id" left join "quest_hooks" on "quest_hooks"."site_id" = "sites"."id" left join "quests" "hook_quest" on "quest_hooks"."quest_id" = "hook_quest"."id" left join "consequences" on "consequences"."affected_site_id" = "sites"."id" left join "factions" on "factions"."hq_site_id" = "sites"."id" left join "faction_influence" on "faction_influence"."site_id" = "sites"."id" left join "foreshadowing" "outgoing_foreshadowing" on "outgoing_foreshadowing"."source_site_id" = "sites"."id" left join "foreshadowing" "incoming_foreshadowing" on "incoming_foreshadowing"."target_site_id" = "sites"."id" left join "item_connections" on "item_connections"."connected_site_id" = "sites"."id" left join "map_groups" on "sites"."map_group_id" = "map_groups"."id" group by "sites"."id", "areas"."id", "regions"."id", "map_groups"."id");--> statement-breakpoint
CREATE VIEW "quest_stage_decision_search_data_view" AS (select "quest_stage_decisions"."id", 'quest_stage_decisions' as "source_table", to_jsonb("quest_stage_decisions".*) as "entity_main", jsonb_build_object('id', "quests"."id", 'name', "quests"."name") as "quest", jsonb_build_object('id', "decision_from_stage"."id", 'name', "decision_from_stage"."name") as "from_stage", CASE WHEN "quest_stage_decisions"."to_quest_stage_id" IS NOT NULL THEN jsonb_build_object('id', "decision_to_stage"."id", 'name', "decision_to_stage"."name") END as "to_stage", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "consequences"."id", 'name', "consequences"."name", 'description', "consequences"."description")) FILTER (WHERE "consequences"."id" IS NOT NULL), '[]'::jsonb) as "consequences" from "quest_stage_decisions" inner join "quest_stages" "decision_from_stage" on "quest_stage_decisions"."from_quest_stage_id" = "decision_from_stage"."id" inner join "quests" on "decision_from_stage"."quest_id" = "quests"."id" left join "quest_stages" "decision_to_stage" on "quest_stage_decisions"."to_quest_stage_id" = "decision_to_stage"."id" left join "consequences" on "consequences"."trigger_quest_stage_decision_id" = "quest_stage_decisions"."id" group by "quest_stage_decisions"."id", "quests"."id", "decision_from_stage"."id", "decision_to_stage"."id");--> statement-breakpoint
CREATE VIEW "quest_stage_search_data_view" AS (select "quest_stages"."id", 'quest_stages' as "source_table", to_jsonb("quest_stages".*) as "entity_main", jsonb_build_object('id', "quests"."id", 'name', "quests"."name") as "quest", CASE WHEN "quest_stages"."site_id" IS NOT NULL THEN jsonb_build_object('id', "sites"."id", 'name', "sites"."name") END as "site", CASE WHEN "quest_stages"."delivery_npc_id" IS NOT NULL THEN jsonb_build_object('id', "npcs"."id", 'name', "npcs"."name") END as "delivery_npc", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('decision', to_jsonb("outgoing_decisions".*), 'toStage', jsonb_build_object('id', "to_stage"."id", 'name', "to_stage"."name"))) FILTER (WHERE "outgoing_decisions"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_decisions", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('decision', to_jsonb("incoming_decisions".*), 'fromStage', jsonb_build_object('id', "from_stage"."id", 'name', "from_stage"."name"))) FILTER (WHERE "incoming_decisions"."id" IS NOT NULL), '[]'::jsonb) as "incoming_decisions", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', "items"."id", 'name', "items"."name")) FILTER (WHERE "items"."id" IS NOT NULL), '[]'::jsonb) as "items", COALESCE(jsonb_agg(DISTINCT jsonb_build_object('involvement', to_jsonb("npc_quest_stage_involvement".*), 'npc', jsonb_build_object('id', "involved_npc"."id", 'name', "involved_npc"."name"))) FILTER (WHERE "npc_quest_stage_involvement"."id" IS NOT NULL), '[]'::jsonb) as "npc_involvement", COALESCE(jsonb_agg(DISTINCT to_jsonb("foreshadowing".*)) FILTER (WHERE "foreshadowing"."id" IS NOT NULL), '[]'::jsonb) as "outgoing_foreshadowing" from "quest_stages" inner join "quests" on "quest_stages"."quest_id" = "quests"."id" left join "sites" on "quest_stages"."site_id" = "sites"."id" left join "npcs" on "quest_stages"."delivery_npc_id" = "npcs"."id" left join "quest_stage_decisions" "outgoing_decisions" on "outgoing_decisions"."from_quest_stage_id" = "quest_stages"."id" left join "quest_stages" "to_stage" on "outgoing_decisions"."to_quest_stage_id" = "to_stage"."id" left join "quest_stage_decisions" "incoming_decisions" on "incoming_decisions"."to_quest_stage_id" = "quest_stages"."id" left join "quest_stages" "from_stage" on "incoming_decisions"."from_quest_stage_id" = "from_stage"."id" left join "item_connections" on "item_connections"."connected_quest_stage_id" = "quest_stages"."id" left join "items" on "item_connections"."source_item_id" = "items"."id" left join "npc_quest_stage_involvement" on "npc_quest_stage_involvement"."quest_stage_id" = "quest_stages"."id" left join "npcs" "involved_npc" on "npc_quest_stage_involvement"."npc_id" = "involved_npc"."id" left join "foreshadowing" on "foreshadowing"."source_quest_stage_id" = "quest_stages"."id" group by "quest_stages"."id", "quests"."id", "sites"."id", "npcs"."id");--> statement-breakpoint
